  none: { end: true, tone: 'bad', v: 'No CRA remedy', x: 'Unless it was a distance or off-premises sale within the 14-day cancellation period (Consumer Contracts Regulations 2013), or the shop has a goodwill returns policy.' },
  when: { q: 'How long since delivery?', o: [['Within 30 days', 'reject'], ['After 30 days', 'repair']] },
  reject: { end: true, tone: 'good', v: 'Short-term right to reject (s22)', x: 'Full refund, within 14 days of the trader agreeing. The consumer may instead choose repair or replacement.' },
  repair: { q: 'Has one repair or replacement been tried and failed, or is it impossible or not done within a reasonable time?', o: [['No', 'rr'], ['Yes', 'final']] },
